source('validation/R/theory.R');source('validation/R/extrema.R');library(data.table)
uv<-function(t,th){r<-1/(-expm1(t));cd<-C_log_derivatives(r,th);ad<-action_barrier_derivatives(r,th);q<-r*(r-1);qp<-2*r-1;c0<-cd['d1']+1/(2*(r-1))-th/(2*r);c1<-cd['d2']-1/(2*(r-1)^2)+th/(2*r^2);U1<--q*(qp*c0+q*c1);V1<-q*(qp*ad['d1']+q*ad['d2']);c(a=unname(-V1),w=unname(-U1/V1))}
z<-fread('validation/data/critical_geometry_UV.csv')[R0>1.1&R0<150&V1<0&U1>0];z<-z[seq(1,.N,by=3)];out<-rbindlist(lapply(seq_len(nrow(z)),function(i){r<-z$R0[i];th<-z$theta[i];t<-log1p(-1/r);h<-min(abs(t)*1e-3,1e-4);v<-cbind(uv(t-h,th),uv(t,th),uv(t+h,th));if(any(v['a',]<=0))return(NULL);data.table(R0=r,theta=th,loga_second=as.numeric((log(v['a',1])-2*log(v['a',2])+log(v['a',3]))/h^2),w_second=as.numeric((v['w',1]-2*v['w',2]+v['w',3])/h^2))}));fwrite(out,'validation/data/kernel_route_checks.csv');print(out[order(-loga_second)][1:5]);print(out[order(w_second)][1:5]);cat('a failures',nrow(out[loga_second>1e-3]),'w failures',nrow(out[w_second< -1e-3]),'of',nrow(out),'\n')
